for m in Cohomology/CechTwistedCoherenceReductionProof; do echo "--- $m"; ls AlgebraicJacobian/$m.lean 2>/dev/null && grep -rn "import AlgebraicJacobian.${m//\//.}" --include=*.lean . 2>/dev/null | grep -v '\.lake' | head -3 || echo "  no importer"; done; echo; echo "=== modules with no importer at all (quick check):"; python3 - <<'PY'
import pathlib,re
root=pathlib.Path('AlgebraicJacobian')
mods={}
for f in root.rglob('*.lean'):
    mods['AlgebraicJacobian.'+str(f.relative_to(root)).replace('/', '.')[:-5]]=f
imported=set()
for f in list(root.rglob('*.lean'))+[pathlib.Path('AlgebraicJacobian.lean')]:
    if not f.exists(): continue
    for line in f.read_text().splitlines():
        m=re.match(r'import (AlgebraicJacobian[\w.]*)',line)
        if m: imported.add(m.group(1))
orph=[m for m in mods if m not in imported]
print(len(orph),'modules with NO importer:')
for m in sorted(orph): print('  ',m)
PY
